package com.mediconnect.office.domain;
import java.util.UUID; import com.mediconnect.shared.audit.AuditableEntity; import jakarta.persistence.*;
@Entity @Table(name="offices") public class OfficeEntity extends AuditableEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,length=120) private String name; @Column(nullable=false,length=255) private String address; @Column(length=50) private String roomNumber; @Column(nullable=false) private boolean active=true; protected OfficeEntity(){} public OfficeEntity(String name,String address,String roomNumber){this.name=name;this.address=address;this.roomNumber=roomNumber;} public UUID getId(){return id;} public String getName(){return name;} public String getAddress(){return address;} public String getRoomNumber(){return roomNumber;} public boolean isActive(){return active;} public void update(String name,String address,String roomNumber,boolean active){this.name=name;this.address=address;this.roomNumber=roomNumber;this.active=active;} }
